public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a call rating
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendCallRatingAsync(InputCall callId = default, int rating = default, string comment = default, CallProblem[] problems = default)
    {

           using var activity =  StartCallActivity("SendCallRatingAsync", typeof(SendCallRating).FullName ?? "SendCallRatingAsync");

           try
           {
             return client.SendCallRatingAsync(callId, rating, comment, problems);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
